package org.sleepwell.app;

import java.util.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class GradedMathTest {
    @Test public void originalSeededAdditionQuestionsAndChoiceOrderRemainUnchanged(){int[] seeds={0,1,19,42,327};String[] expected={"8,18,24,26,25,30","17,12,33,26,31,29","7,4,11,12,10,8","10,5,15,18,19,11","3,16,19,20,21,17"};for(int n=0;n<seeds.length;n++){MathTask task=MathTask.create(new Random(seeds[n]));assertEquals(expected[n],task.encode());assertEquals(expected[n],MathTask.decode(expected[n]).encode());assertTrue(task.matches(MathSettings.LEGACY));}}
    @Test public void eachGradeAndOperatorProducesOnlyValidUniqueExactlySolvableQuestions(){Random random=new Random(711);for(MathSettings.Level grade:MathSettings.Level.values())for(MathSettings.Operator operator:MathSettings.Operator.values())for(boolean typed:new boolean[]{false,true}){MathSettings settings=new MathSettings(grade,operator.bit,typed);for(int n=0;n<400;n++){MathTask task=MathTask.create(random,settings);assertEquals(operator,task.operator);assertEquals(4,new HashSet<>(task.options).size());assertEquals(1,task.options.stream().filter(task::accepts).count());long expected=switch(operator){case ADD->(long)task.left+task.right;case SUBTRACT->(long)task.left-task.right;case MULTIPLY->(long)task.left*task.right;case DIVIDE->(long)task.left/task.right;};assertEquals(expected,task.answer());assertTrue(task.answer()>=0);assertTrue(task.acceptsTyped(""+expected));if(operator==MathSettings.Operator.DIVIDE){assertNotEquals(0,task.right);assertEquals(0,task.left%task.right);}if(operator==MathSettings.Operator.ADD||operator==MathSettings.Operator.SUBTRACT){assertTrue(task.left>=grade.minimum&&task.left<=grade.maximum);assertTrue(task.right>=grade.minimum&&task.right<=grade.maximum);}else if(operator==MathSettings.Operator.MULTIPLY){assertTrue(task.left>=grade.factorMinimum&&task.left<=grade.factorMaximum);assertTrue(task.right>=grade.factorMinimum&&task.right<=grade.factorMaximum);}else{assertTrue(task.right>=grade.factorMinimum&&task.right<=grade.factorMaximum);assertTrue(task.answer()>=grade.factorMinimum&&task.answer()<=grade.factorMaximum);}}}}
    @Test public void operatorSetsNeverLeakDisabledOperatorsAndEveryEnabledOperatorCanAppear(){for(int mask=1;mask<=15;mask++){MathSettings settings=new MathSettings(MathSettings.Level.MEDIUM,mask,false);Set<MathSettings.Operator> seen=new HashSet<>();Random random=new Random(18);for(int n=0;n<300;n++){MathTask task=MathTask.create(random,settings);assertTrue(settings.permits(task.operator));seen.add(task.operator);}assertEquals(new HashSet<>(settings.enabled()),seen);}}
    @Test public void gradeIsIndependentOfRoundsAndSurvivesRoutineReorderAndReplace(){MathSettings hard=new MathSettings(MathSettings.Level.HARD,14,true);ChallengeRoutine routine=new ChallengeRoutine(List.of(new ChallengeRoutine.Task("Math",3),new ChallengeRoutine.Task("Math",2,0,hard),new ChallengeRoutine.Task("Retype",1)));assertEquals(6,routine.units());assertEquals(MathSettings.LEGACY,routine.at(0).task.math);assertEquals(hard,routine.at(3).task.math);assertEquals(hard,routine.move(1,0).at(0).task.math);ChallengeRoutine updated=routine.replace(1,new ChallengeRoutine.Task("Math",5,0,hard));assertEquals(9,updated.units());assertEquals(hard,updated.at(7).task.math);assertEquals(2,routine.tasks.get(1).rounds);}
    @Test public void allGradesAndAnswerModesRetainExactOperatorOperandsAndChoiceOrder(){for(MathSettings.Level level:MathSettings.Level.values())for(int mask=1;mask<=15;mask++)for(boolean typed:new boolean[]{false,true}){MathSettings settings=new MathSettings(level,mask,typed);MathTask original=MathTask.create(new Random(91),settings),restored=MathTask.decode(original.encode());assertEquals(original.encode(),restored.encode());assertEquals(original.question(),restored.question());assertEquals(original.spoken(),restored.spoken());assertEquals(original.answer(),restored.answer());assertTrue(restored.matches(settings));assertEquals(original.options,restored.options);}}
    @Test public void restoringAnOldQuestionCannotIgnoreNewTaskSettings(){MathTask original=MathTask.create(new Random(5));assertFalse(original.matches(new MathSettings(MathSettings.Level.HARD,1,false)));assertFalse(original.matches(new MathSettings(MathSettings.Level.MEDIUM,2,false)));assertFalse(original.matches(new MathSettings(MathSettings.Level.MEDIUM,1,true)));assertTrue(MathTask.decode(original.encode()).matches(MathSettings.LEGACY));}
    @Test public void typedAnswersRequireTheWholeExactIntegerNotAnExpressionPrefixOrDecimal(){MathTask task=new MathTask(3,4,List.of(7,6,8,9));for(String wrong:new String[]{null,""," ","7.0","7abc","3+4","+7","-7","1e1","70000000000000000000","6","8"})assertFalse("Reject "+wrong,task.acceptsTyped(wrong));assertTrue(task.acceptsTyped("7"));assertTrue(task.acceptsTyped(" 007 "));MathSettings subtract=new MathSettings(MathSettings.Level.EASY,2,true);MathTask zero=new MathTask(3,3,List.of(0,1,2,3),subtract,MathSettings.Operator.SUBTRACT);assertTrue(zero.acceptsTyped("0"));assertFalse(zero.acceptsTyped("-0"));}
    @Test public void regionalDecimalDigitsNormalizeToTheWholeExactAnswer(){MathTask seven=new MathTask(3,4,List.of(7,6,8,9));for(String valid:List.of("٧","۷","७","๗","７","𝟟"," ٠۰۰٧ "))assertTrue(valid,seven.acceptsTyped(valid));MathTask fourteen=new MathTask(7,7,List.of(14,13,15,16));assertTrue(fourteen.acceptsTyped("١٤"));assertTrue(fourteen.acceptsTyped("۱۴"));assertTrue(fourteen.acceptsTyped("१४"));assertFalse(seven.acceptsTyped("٧١"));assertFalse(fourteen.acceptsTyped("١٣"));MathSettings subtract=new MathSettings(MathSettings.Level.EASY,2,true);MathTask zero=new MathTask(3,3,List.of(0,1,2,3),subtract,MathSettings.Operator.SUBTRACT);assertTrue(zero.acceptsTyped("٠"));assertTrue(zero.acceptsTyped("۰۰"));}
    @Test public void regionalInputRejectsNondecimalNumericGlyphsSignsFractionsAndOverflow(){MathTask seven=new MathTask(3,4,List.of(7,6,8,9));for(String invalid:List.of("+٧","−٧","-٧","+","−","½","Ⅶ","⑦","⁷","٧٫٠","٧.٠","٧/١","٧ ٠","٧x","٢١٤٧٤٨٣٦٤٨","۹۹۹۹۹۹۹۹۹۹۹۹۹۹۹۹۹۹۹۹۹","000007","\uD835"))assertFalse(invalid,seven.acceptsTyped(invalid));}
    @Test public void invalidCachedQuestionsCannotCreateDivideByZeroOrMultipleCorrectChoices(){for(String bad:List.of("3,4,7,7,8,9","3,4,8,9,10,11","-3,4,1,2,3,4","3.5,4,7,8,9,10","3,4,7,8,9,10,","m2,HARD,8,typed,DIVIDE,100,0,1,2,3,4","m2,HARD,8,typed,DIVIDE,101,10,10,11,12,13","m2,HARD,1,typed,MULTIPLY,10,10,100,101,102,103","m2,HARD,1,prompt,ADD,20,20,40,41,42,43","m2,HARD,0,typed,ADD,20,20,40,41,42,43"))assertThrows(bad,IllegalArgumentException.class,()->MathTask.decode(bad));}
    @Test public void boundedDistractorsTerminateEvenWithAConstantRandomSource(){Random constant=new Random(){@Override public int nextInt(int bound){return 0;}};MathTask task=MathTask.create(constant,new MathSettings(MathSettings.Level.EASY,2,true));assertEquals(0,task.answer());assertEquals(4,new HashSet<>(task.options).size());assertEquals(1,task.options.stream().filter(task::accepts).count());}
    @Test public void unsupportedEmptyOperatorsAndArithmeticOnOtherTaskTypesAreRejected(){assertThrows(IllegalArgumentException.class,()->new MathSettings(MathSettings.Level.EASY,0,false));assertThrows(IllegalArgumentException.class,()->new MathSettings(MathSettings.Level.EASY,16,false));assertThrows(IllegalArgumentException.class,()->MathSettings.LEGACY.toggle(MathSettings.Operator.ADD,false));assertThrows(IllegalArgumentException.class,()->new ChallengeRoutine.Task("Retype",1,0,new MathSettings(MathSettings.Level.HARD,1,false)));assertEquals(MathSettings.LEGACY,ChallengeRoutine.legacy("Unknown",4).at(0).task.math);assertEquals(4,ChallengeRoutine.legacy("Math",4).units());}
}
